SELECT id, store_id, SUM(quantity) OVER (PARTITION BY product_id, store_id) AS product_id_sum_quantity, LAG(quantity, 1, 0) OVER (PARTITION BY YEAR(last_restock), product_id ORDER BY quantity, id) AS prev_quantity, AVG(quantity) OVER (PARTITION BY YEAR(last_restock), store_id ORDER BY last_restock, id ROWS BETWEEN 2 PRECEDING AND 1 PRECEDING) AS quantity_avg_2_prior, LAG(quantity, 2) OVER (ORDER BY quantity, id) AS prev_quantity_2 FROM inventory WHERE quantity BETWEEN 63 AND 137;
